// === INPUT ==============================================================
const keys = new Set();
document.addEventListener('keydown', (ev) => {
  if (ev.key === 'r' || ev.key === 'R') { reset(); return; }
  keys.add(ev.key);
  // Prevent scrolling on space
  if (ev.key === ' ') ev.preventDefault();
});
document.addEventListener('keyup', (ev) => {
  keys.delete(ev.key);
});
document.addEventListener('mousedown', (ev) => {
  // start pulse on click/tap
  if (!pulseActive) {
    pulseActive = true;
    pulseTimer = 0;
    beep(400, 0.1);
  }
});
restartBtn.addEventListener('click', reset);

function reset() {
  // Reinitialize state variables
  player.x = W/2; player.y = H/2; player.angle = 0; player.vx = 0; player.vy = 0;
  hazards.length = 0;
  score = 0;
  phase = "playing";
  pulseActive = false;
  pulseTimer = 0;
  startLoop();
}

